def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if all(v == 0 for v in grid[r])]
    sep_cols = [c for c in range(w) if all(grid[r][c] == 0 for r in range(h))]

    def bands(size, separators):
        result = []
        start = 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < size:
            result.append((start, size))
        return result

    rows, cols = bands(h, sep_rows), bands(w, sep_cols)
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = min((v for v in counts if v != background),
                 key=lambda v: counts[v], default=background)

    return [
        [
            1 if sum(grid[r][c] == marker
                     for r in range(r0, r1) for c in range(c0, c1)) == 2
            else background
            for c0, c1 in cols
        ]
        for r0, r1 in rows
    ]
